        return new TransferOrder(1L, "O-1", 1, "CASE-A", "CASE-B", status, validFrom, validTo, T);
    }

    @Test
    void normalizeKeysSortsAndKeepsAllKeys() {
        List<String> normalized = CaseTransferService.normalizeKeys(List.of("ev-3", "ev-1", "ev-2"));
